import{_ as e,o as a,c as o,a0 as r}from"./chunks/framework.CNXp-E7Q.js";const p=JSON.parse('{"title":"bupha vs hosted CI","description":"","frontmatter":{},"headers":[],"relativePath":"comparison.md","filePath":"comparison.md"}'),d={name:"comparison.md"};function s(n,t,i,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="bupha-vs-hosted-ci" tabindex="-1">bupha vs hosted CI <a class="header-anchor" href="#bupha-vs-hosted-ci" aria-label="Permalink to &quot;bupha vs hosted CI&quot;">​</a></h1><p>bupha runs push-triggered CI on self-controlled hardware — not a GHA replacement at fleet scale.</p><h2 id="vs-github-actions" tabindex="-1">vs GitHub Actions <a class="header-anchor" href="#vs-github-actions" aria-label="Permalink to &quot;vs GitHub Actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>bupha</th><th>GitHub Actions</th></tr></thead><tbody><tr><td>compute</td><td>your box</td><td>managed fleet</td></tr><tr><td>queue</td><td>latest-wins + bounded <code>all</code>, no cold start</td><td>unlimited parallelism, queue wait</td></tr><tr><td>secrets</td><td>never leave the machine</td><td>hosted on GitHub</td></tr><tr><td>cache</td><td>your backend — local disk or your S3/R2/minio</td><td>hosted cache</td></tr><tr><td>pipeline def</td><td>your runner — <code>ci.sh</code> or dagger module</td><td>YAML DSL + marketplace actions</td></tr><tr><td>local == CI</td><td><code>bupha run</code> is literally the same path</td><td><code>act</code> approximates</td></tr><tr><td>batching</td><td>supersede built-in, honest &quot;cancelled&quot; statuses</td><td><code>concurrency</code> groups</td></tr><tr><td>scale</td><td>one worker, serialized runs</td><td>matrix/fleet</td></tr><tr><td>cost</td><td>your box only</td><td>minutes billing</td></tr></tbody></table><p><strong>When GHA is better:</strong> you need parallelism, matrices across OSes, hosted macOS/Windows builds, or marketplace actions. <strong>When bupha fits:</strong> instant feedback on self-owned hardware, secrets that never leave the machine, warm caches on self-owned storage, no YAML.</p><h2 id="vs-others" tabindex="-1">vs others <a class="header-anchor" href="#vs-others" aria-label="Permalink to &quot;vs others&quot;">​</a></h2><ul><li><strong>Jenkins/Buildkite</strong> — bupha is a single binary with a TOML file, not a server product to operate.</li><li><strong>Woodpecker/Forgejo CI</strong> — bupha is forge-webhook driven and much smaller; those are full pipeline platforms.</li><li><strong>self-hosted GHA runner</strong> — bupha is lighter (no runner service, no org config) but has no matrix or marketplace.</li></ul>',7)])])}const b=e(d,[["render",s]]);export{p as __pageData,b as default};
